	cp	xwa, 1
	jr	z, SectionInfo_Sec00_RecSize
	or	xwa, xwa
	jr	z, SectionInfo_Sec00_Base
	ld	xhl, 0:i3
	ret
SectionInfo_Sec00_Base:
